#include <stdint.h>
#include <stdio.h>
#include <stddef.h>
#include "stm32f4xx_hal.h"
#include "se050_driver.h"
#include "fingerprint_driver.h"

typedef enum {
    STATE_IDLE = 0,
    STATE_WAIT_FINGERPRINT,
    STATE_VERIFY_BIOMETRIC,
    STATE_CRYPTO_SIGN,
    STATE_ERROR
} DeviceState_t;

UART_HandleTypeDef huart2;

void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_I2C1_Init(void);
static void MX_USART2_UART_Init(void);

int main(void)
{
  HAL_Init();
  SystemClock_Config();

  MX_GPIO_Init();
  MX_I2C1_Init();
  MX_USART2_UART_Init();

  /* Initialize Drivers */
  SE050_Init();
  FP_Init();

  DeviceState_t currentState = STATE_IDLE;
  uint16_t matched_user_id = 0;

  while (1)
  {
    switch (currentState) 
    {
      case STATE_IDLE:
        /* รอสัญญาณเริ่มทำงาน */
        currentState = STATE_WAIT_FINGERPRINT;
        break;

      case STATE_WAIT_FINGERPRINT:
        /* รอการแตะนิ้วเพื่อสแกนและยืนยันตัวตน */
        if (FP_CaptureAndMatch(&matched_user_id)) {
            currentState = STATE_CRYPTO_SIGN;
        } else {
            currentState = STATE_ERROR;
        }
        break;

      case STATE_CRYPTO_SIGN:
        {
            uint8_t tx_hash[32] = {0x01, 0x02 /* Hash จาก App */};
            uint8_t signature[64];
            size_t sig_len = sizeof(signature);

            /* ปลดล็อกลายเซ็นดิจิทัลเฉพาะเมื่อสแกนนิ้วผ่านเท่านั้น */
            if (SE050_SignDigest(SE050_KEY_ID_SECP256K1, tx_hash, 32, signature, &sig_len)) {
                currentState = STATE_IDLE;
            } else {
                currentState = STATE_ERROR;
            }
        }
        break;

      case STATE_ERROR:
        /* Reset สภาวะกลับไปรอใหม่ */
        currentState = STATE_IDLE;
        break;

      default:
        currentState = STATE_IDLE;
        break;
    }
  }
}

static void MX_I2C1_Init(void) {}
static void MX_USART2_UART_Init(void) {}
static void MX_GPIO_Init(void) {}
void SystemClock_Config(void) {}